"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["28168"],{2299(e){e.exports=JSON.parse('{"id":"FIN-227","slug":"investment-objective","term":"Investment Objective","also_known_as":[],"difficulty":"Beginner","definition":"An investment objective is the specific goal an investor wants their money to achieve, such as long-term growth, regular income or keeping capital safe.","explanation":["Before choosing investments, it helps to be clear about what the money is for. The investment objective guides every other decision, including which assets to hold, how much risk to accept and how long to stay invested.","Common objectives include capital growth, aiming to increase the value of investments over the long term; income, aiming to receive regular payments such as dividends or interest; capital preservation, aiming above all to avoid losses; and a balance of growth and income.","For example, a 30-year-old saving for retirement might choose long-term growth and accept large ups and downs along the way. A retired person relying on investments for living costs might prioritise steady income and lower volatility. Someone saving for a home deposit needed in two years would likely prioritise keeping the money safe.","Investment funds state their objectives in their documents, so investors can choose funds that match their own goals. Financial advisers also start by understanding a client\'s objectives, time horizon and tolerance for risk."],"note":"","total":1500,"prev":{"slug":"investment-horizon","term":"Investment Horizon"},"next":{"slug":"investment-value","term":"Investment Value"}}')}}]);